def chunk(doc, title, max_chars=300):
    out, sec, cl = [], "", None
    def flush():
        if not cl: return
        no, lead, subs = cl
        path = f"{title} > {sec} > {no}"
        whole = "\n".join([path, lead, *subs])
        if len(whole) <= max_chars or not subs:
            return out.append(whole)
        for s in subs:  # {{lead-in on each}}
            out.append("\n".join(
                [path + s[:3], lead, s]))
    for ln in doc.splitlines():
        if re.match(r"\d+\. ", ln):
            flush(); cl = None; sec = ln
        elif m := re.match(r"(\d+\.\d+) ", ln):
            flush(); cl = (m[1], ln, [])
        elif cl and re.match(r"\([a-z]\) ", ln):
            cl[2].append(ln)
    flush(); return out

def refs(chunk, own):
    body = chunk.split("\n", 1)[1]
    found = re.findall(r"\b\d+\.\d+\b", body)
    return [r for r in dict.fromkeys(found)
            if r != own]

